// static
bool StructTraits<::critical_actions::mojom::CriticalActionItem::DataView, ::critical_actions::mojom::CriticalActionItemPtr>::Read(
    ::critical_actions::mojom::CriticalActionItem::DataView input,
    ::critical_actions::mojom::CriticalActionItemPtr* output) {
  bool success = true;
  ::critical_actions::mojom::CriticalActionItemPtr result(::critical_actions::mojom::CriticalActionItem::New());
  
      if (success && !input.ReadCriticalActionId(&result->critical_action_id))
        success = false;
      if (success)
        result->timestamp_raw = input.timestamp_raw();
      if (success && !input.ReadTimestampStr(&result->timestamp_str))
        success = false;
      if (success)
        result->visit_id = input.visit_id();
      if (success && !input.ReadConversationId(&result->conversation_id))
        success = false;
      if (success && !input.ReadActorTaskId(&result->actor_task_id))
        success = false;
      if (success)
        result->action_type = input.action_type();
      if (success && !input.ReadActionTypeStr(&result->action_type_str))
        success = false;
      if (success)
        result->action_source = input.action_source();
      if (success && !input.ReadActionSourceStr(&result->action_source_str))
        success = false;
      if (success && !input.ReadLabel(&result->label))
        success = false;
      if (success && !input.ReadTooltip(&result->tooltip))
        success = false;
      if (success && !input.ReadMetadata(&result->metadata))
        success = false;
  *output = std::move(result);
  return success;
}


