  ::critical_actions::mojom::CriticalActionsListPtr result(::critical_actions::mojom::CriticalActionsList::New());
  
      if (success && !input.ReadEntries(&result->entries))
        success = false;
      if (success)
        result->total_entries = input.total_entries();
