PageHandlerAsyncWaiter::PageHandlerAsyncWaiter(
    PageHandler* proxy) : proxy_(proxy) {}

PageHandlerAsyncWaiter::~PageHandlerAsyncWaiter() = default;


void PageHandlerAsyncWaiter::GetCriticalActions(
    uint32_t page_index, uint32_t page_size, const std::optional<std::string>& search_query, std::optional<int32_t> action_type_filter, CriticalActionsQueryResultPtr* out_result) {
  base::RunLoop loop;
  proxy_->GetCriticalActions(
      std::move(page_index),
      std::move(page_size),
      std::move(search_query),
      std::move(action_type_filter),
      base::BindOnce(
          [](base::RunLoop* loop,
             CriticalActionsQueryResultPtr* out_result
,
             CriticalActionsQueryResultPtr result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

CriticalActionsQueryResultPtr PageHandlerAsyncWaiter::GetCriticalActions(
    uint32_t page_index, uint32_t page_size, const std::optional<std::string>& search_query, std::optional<int32_t> action_type_filter) {
  CriticalActionsQueryResultPtr async_wait_result;
  GetCriticalActions(std::move(page_index),std::move(page_size),std::move(search_query),std::move(action_type_filter),&async_wait_result);
  return async_wait_result;
}

void PageHandlerAsyncWaiter::DeleteCriticalAction(
    const std::string& critical_action_id, bool* out_success) {
  base::RunLoop loop;
  proxy_->DeleteCriticalAction(
      std::move(critical_action_id),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

bool PageHandlerAsyncWaiter::DeleteCriticalAction(
    const std::string& critical_action_id) {
  bool async_wait_result;
  DeleteCriticalAction(std::move(critical_action_id),&async_wait_result);
  return async_wait_result;
}

void PageHandlerAsyncWaiter::ClearAllCriticalActions(
    bool* out_success) {
  base::RunLoop loop;
  proxy_->ClearAllCriticalActions(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

bool PageHandlerAsyncWaiter::ClearAllCriticalActions(
    ) {
  bool async_wait_result;
  ClearAllCriticalActions(&async_wait_result);
  return async_wait_result;
}




